  ln -sf /workspace/executable /tmp/xz-test/$name 2>/dev/null
  result=$(echo "hello world" | /tmp/xz-test/$name 2>&1 | od -An -tx1 | head -1 | tr -d ' \n')
  case "$result" in
    *fd377a585a*) kind="xz-compress" ;;
    *5d00008000*) kind="lzma-compress" ;;
    *68656c6c6f*) kind="decompress-or-passthrough" ;;
    *) kind="other:$result" ;;
  esac
  echo "$name => $kind"
done

