def parse_nonneg_int(s, name=None):
    """Parse as non-negative integer."""
    if s is None:
        message_fatal(": Value is not a non-negative decimal integer")
    # xz accepts values with suffix like 'KiB', 'MiB' etc. for some options
    if not s or not s[0].isdigit():
        message_fatal("%s: Value is not a non-negative decimal integer", s)
    try:
        v = int(s)
    except ValueError:
        message_fatal("%s: Value is not a non-negative decimal integer", s)
    if v < 0:
        message_fatal("%s: Value is not a non-negative decimal integer", s)
    return v


def parse_size(s, name=None):
    """Parse size with optional suffix: K, Ki, KiB, M, Mi, MiB, G, Gi, GiB (1000 or 1024 based)."""
    if s is None or not s:
        message_fatal("%s: Invalid value", s if s is not None else "")
    # Find suffix
    i = 0
    while i < len(s) and (s[i].isdigit()):
        i += 1
    num = s[:i]
    suffix = s[i:]
    if not num:
        message_fatal("%s: Value is not a non-negative decimal integer", s)
    v = int(num)
    mult = 1
    if suffix == "":
        mult = 1
    else:
        su = suffix.lower().rstrip('b').rstrip('i')
        if su == "":
            mult = 1
        elif su == "k":
            mult = 1024 if 'i' in suffix.lower() or 'B' in suffix else 1000
            # Interpret: 'k' -> 1024, 'kB' -> 1000, 'KiB' -> 1024
            if suffix in ("k", "K"):
                mult = 1024
            elif suffix in ("kB", "KB"):
                mult = 1000
            elif suffix in ("KiB", "kiB", "Ki", "ki"):
                mult = 1024
        elif su == "m":
            if suffix in ("m", "M"):
                mult = 1024 * 1024
            elif suffix in ("mB", "MB"):
                mult = 1000 * 1000
            elif suffix in ("MiB", "miB", "Mi", "mi"):
                mult = 1024 * 1024
        elif su == "g":
            if suffix in ("g", "G"):
                mult = 1024 ** 3
            elif suffix in ("gB", "GB"):
                mult = 1000 ** 3
            elif suffix in ("GiB", "giB", "Gi", "gi"):
                mult = 1024 ** 3
        else:
            message_fatal("%s: Invalid multiplier suffix", s)
    return v * mult


def parse_memlimit(s):
    """Parse memlimit: accepts 0, bytes, or percentage."""
    if s == "0":
        return 0
    if s.endswith("%"):
        p = int(s[:-1])
        if p < 1 or p > 100:
            message_fatal("%s: Invalid value", s)
        return (_get_total_ram() * p) // 100
    if s == "max":
        return 2**63 - 1
    return parse_size(s)


def set_check(opts, name):
    table = {
        "none": CHECK_NONE,
        "crc32": CHECK_CRC32,
        "crc64": CHECK_CRC64,
        "sha256": CHECK_SHA256,
    }
    key = name.lower()
    if key not in table:
        message_fatal("%s: Unsupported integrity check type", name)
    opts.check = table[key]
    opts.check_set = True


def set_format(opts, name):
    table = {
        "auto": FORMAT_AUTO,
        "xz": FORMAT_XZ,
        "lzma": FORMAT_LZMA,
        "alone": FORMAT_LZMA,
        "lzip": FORMAT_LZIP,
        "raw": FORMAT_RAW,
    }
    key = name.lower()
    if key not in table:
        message_fatal("%s: Unsupported file format", name)
    opts.format = table[key]
    opts.format_set = True


def apply_options(opts_list, opts):
    for name, value, is_short in opts_list:
        if name == 'compress':
            opts.mode = MODE_COMPRESS
        elif name in ('decompress', 'uncompress'):
            opts.mode = MODE_DECOMPRESS
        elif name == 'test':
            opts.mode = MODE_TEST
        elif name == 'list':
            opts.mode = MODE_LIST
        elif name == 'keep':
            opts.keep = True
        elif name == 'force':
            opts.force = True
            opts.keep = False
        elif name in ('stdout', 'to-stdout'):
            opts.stdout = True
            opts.keep = True
        elif name == 'no-sync':
            opts.no_sync = True
        elif name == 'single-stream':
            opts.single_stream = True
        elif name == 'no-sparse':
            opts.no_sparse = True
        elif name == 'suffix':
            if not value or len(value) < 1 or value.startswith('-'):
                message_fatal("%s: Invalid filename suffix", value)
            opts.suffix = value
        elif name == 'files':
            opts.files_input = value if value else "-"
            opts.files0 = False
        elif name == 'files0':
            opts.files_input = value if value else "-"
            opts.files0 = True
        elif name == 'format':
            set_format(opts, value)
        elif name == 'check':
            set_check(opts, value)
        elif name == 'ignore-check':
            opts.ignore_check = True
        elif name == 'preset':
            opts.preset = int(value)
            opts.preset_set = True
        elif name == 'extreme':
            opts.extreme = True
        elif name == 'threads':
            opts.threads = parse_nonneg_int(value)
        elif name == 'block-size':
            opts.block_size = parse_size(value)
        elif name == 'block-list':
            opts.block_list = value
        elif name == 'flush-timeout':
            opts.flush_timeout = parse_nonneg_int(value)
        elif name in ('memlimit-compress',):
            opts.memlimit_c = parse_memlimit(value)
        elif name in ('memlimit-decompress',):
            opts.memlimit_d = parse_memlimit(value)
        elif name in ('memlimit-mt-decompress',):
            opts.memlimit_mt_d = parse_memlimit(value)
        elif name in ('memlimit', 'memory'):
            v = parse_memlimit(value)
            opts.memlimit_c = v
            opts.memlimit_d = v
            opts.memlimit_mt_d = v
        elif name == 'no-adjust':
            opts.no_adjust = True
        elif name in ('filters',) or (name.startswith('filters') and name[7:].isdigit()):
            opts.filters = value
        elif name == 'filters-help':
            show_filters_help()
        elif name in ('lzma1', 'lzma2', 'x86', 'arm', 'armthumb', 'arm64',
                      'powerpc', 'ia64', 'sparc', 'riscv', 'delta'):
            # Filter chain (we mostly ignore specifics, but accept them)
            pass
        elif name == 'quiet':
            opts.quiet += 1
            opts.verbose = 0
        elif name == 'verbose':
            opts.verbose += 1
            opts.quiet = 0
        elif name == 'no-warn':
            opts.no_warn = True
        elif name == 'robot':
            opts.robot = True
        elif name == 'info-memory':
            show_info_memory(opts)
        elif name == 'help':
            show_help(False)
        elif name == 'long-help':
            show_help(True)
        elif name == 'version':
            show_version(opts.robot)
        else:
            message_fatal("Unknown option: %s", name)


