        CHECK_CRC32: lzma.CHECK_CRC32,
        CHECK_CRC64: lzma.CHECK_CRC64,
        CHECK_SHA256: lzma.CHECK_SHA256,
    }
    return m.get(opts.check, lzma.CHECK_CRC64)


def _lzma_format(opts, for_decomp=False):
    if opts.format == FORMAT_XZ:
        return lzma.FORMAT_XZ
    elif opts.format == FORMAT_LZMA:
        return lzma.FORMAT_ALONE
    elif opts.format == FORMAT_RAW:
        return lzma.FORMAT_RAW
    elif opts.format == FORMAT_AUTO:
        if for_decomp:
            return lzma.FORMAT_AUTO
        return lzma.FORMAT_XZ
    elif opts.format == FORMAT_LZIP:
        # Python lzma module doesn't support lzip directly, but 5.2.5+ maybe
        try:
            return lzma.FORMAT_LZIP
        except AttributeError:
            return lzma.FORMAT_AUTO
    return lzma.FORMAT_XZ


def compress_stream(inp_fd, out_fd, opts):
    fmt = _lzma_format(opts)
    if fmt == lzma.FORMAT_ALONE:
        # LZMA1 doesn't support check
        enc = lzma.LZMACompressor(format=fmt, preset=_lzma_presets(opts))
    elif fmt == lzma.FORMAT_RAW:
        filters = [{"id": lzma.FILTER_LZMA2, "preset": _lzma_presets(opts)}]
        enc = lzma.LZMACompressor(format=fmt, filters=filters)
    else:
        enc = lzma.LZMACompressor(format=fmt, preset=_lzma_presets(opts),
                                   check=_lzma_check(opts))
    bufsize = 65536
    uncomp_size = 0
    comp_size = 0
    while True:
        chunk = os.read(inp_fd, bufsize)
        if not chunk:
            break
        uncomp_size += len(chunk)
        data = enc.compress(chunk)
        if data:
            os.write(out_fd, data)
            comp_size += len(data)
    tail = enc.flush()
    if tail:
        os.write(out_fd, tail)
        comp_size += len(tail)
    return uncomp_size, comp_size


def decompress_stream(inp_fd, out_fd, opts):
    fmt = _lzma_format(opts, for_decomp=True)
    uncomp_size = 0
    comp_size = 0
    bufsize = 65536
    # Loop for multiple streams
    pending = b""
    while True:
        if fmt == lzma.FORMAT_RAW:
            filters = [{"id": lzma.FILTER_LZMA2, "preset": lzma.PRESET_DEFAULT}]
            dec = lzma.LZMADecompressor(format=fmt, filters=filters)
        else:
            dec = lzma.LZMADecompressor(format=fmt)
        while not dec.eof:
            if pending:
                chunk = pending
                pending = b""
            else:
                chunk = os.read(inp_fd, bufsize)
            if not chunk:
                if not dec.eof:
                    raise lzma.LZMAError("unexpected end of input")
                break
            comp_size += len(chunk)
            try:
                out = dec.decompress(chunk)
            except lzma.LZMAError:
                raise
            if out:
                os.write(out_fd, out)
                uncomp_size += len(out)
        if not dec.eof:
            break
        # Leftover input after EOF
        pending = dec.unused_data
        if opts.single_stream:
            if pending:
                # Subtract pending from comp_size to match
                comp_size -= len(pending)
            break
        if not pending:
            # Check if there's more input in the stream
            more = os.read(inp_fd, bufsize)
            if not more:
                break
            # Re-init decompressor with leftover
            pending = more
            continue
        # There's more data - might be next stream or padding
        # Skip stream padding (4-byte aligned null bytes)
        # For xz, padding between streams is null bytes aligned to 4 bytes
        # Actually lzma module expects to re-init for next stream
        continue
    return uncomp_size, comp_size


