# ============ File coder: main file processing =============

def is_regular_or_symlink_to_regular(path):
    try:
        st = os.stat(path)
    except OSError:
        return False
    return stat.S_ISREG(st.st_mode)


def is_symlink(path):
    try:
        return stat.S_ISLNK(os.lstat(path).st_mode)
    except OSError:
        return False


def input_checks(path, opts):
    """Check if input file is suitable. Return (ok, is_stdin)."""
    if path == "-":
        return True, True
    try:
        lst = os.lstat(path)
    except FileNotFoundError:
        message_error("%s: No such file or directory", path)
        return False, False
    except OSError as e:
        message_error("%s: %s", path, e.strerror)
        return False, False
    if stat.S_ISDIR(lst.st_mode):
        message_error("%s: Is a directory, skipping", path)
        return False, False
    if stat.S_ISLNK(lst.st_mode):
        if not opts.force and not opts.stdout:
            message_warning("%s: Is a symbolic link, skipping", path, opts=opts)
            return False, False
    # Check it's a regular file after following symlinks
    try:
        st = os.stat(path)
    except OSError as e:
        message_error("%s: %s", path, e.strerror)
        return False, False
    if not stat.S_ISREG(st.st_mode):
        message_warning("%s: Not a regular file, skipping", path, opts=opts)
        return False, False
    # Check hard links (>1 link) without -f or -c
    if st.st_nlink > 1 and not opts.force and not opts.stdout and opts.mode in (MODE_COMPRESS, MODE_DECOMPRESS):
        message_warning("%s: File has %d other links, skipping",
                        path, st.st_nlink - 1, opts=opts)
        return False, False
    return True, False


